import subprocess
result = subprocess.run(['pdftotext', 'main.pdf', '-'], capture_output=True, text=True)
lines = result.stdout.split('\n')
page = 1
for i, line in enumerate(lines):
    if line.strip() == '' and i > 0 and lines[i-1].strip() == '':
        continue
    if '\x0c' in line:
        page += 1
    if 'Conclusion' in line and page <= 10:
        print(f'Page {page}: {line.strip()[:80]}')
    if 'Limitations' in line and page <= 10:
        print(f'Page {page}: {line.strip()[:80]}')
    if 'References' in line and page <= 12:
        print(f'Page {page}: {line.strip()[:80]}')
